// Human pages keep people, named agents, and short-lived conversations ahead of connection administration.
package relay

// HTML maxlength counts UTF-16 units; 80 admits 40 astral characters, and the server enforces 40 Unicode characters.
const humanTemplates = `
{{define "human-alerts"}}{{if .Problem}}<p class="problem" role="alert" id="problem"><strong>오류</strong> {{.Problem}}</p>{{end}}{{if .Notice}}<p class="note" role="status">{{.Notice}}</p>{{end}}{{end}}
{{define "human-head"}}<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>{{or .Title "요청 승인"}} · KnowsLink</title>` + memberStyle + `
<a class="skip" href="#main">본문으로 건너뛰기</a><header class="top"><a class="brand" href="/home">KnowsLink</a><a href="/home/account"{{if eq .Section "account"}} aria-current="page"{{end}}>내 계정</a></header>{{end}}
{{define "human-nav"}}<nav class="nav" aria-label="주요 메뉴"><a href="/home"{{if eq .Section "conversations"}} aria-current="page"{{end}}>대화</a><a href="/home/friends"{{if eq .Section "friends"}} aria-current="page"{{end}}>친구</a><a href="/home/agents"{{if eq .Section "agents"}} aria-current="page"{{end}}>내 에이전트</a></nav>{{end}}
{{define "human-agent-label"}}{{if .Name}}{{.Name}}{{else}}이름 없는 에이전트{{end}}{{if .Client}} / {{.Client}}{{end}}{{if .Short}} / {{.Short}}{{end}}{{end}}
{{define "human-my-code-help"}}<p id="my-code-help" class="muted">친구에게 이 코드를 직접 공유하세요. 입력란에서 전체 선택(Ctrl+A 또는 ⌘A)한 뒤 복사(Ctrl+C 또는 ⌘C)합니다. 이 코드는 친구 요청을 찾는 데만 쓰이며 로그인이나 연결 권한이 아닙니다.</p>{{end}}
{{define "human-retention"}}<div class="retention"><p class="muted">메시지는 24시간 안에 사라집니다</p><details><summary>보존 안내</summary><p class="muted">각 메시지는 수락 시각부터 최대 24시간 보관합니다. 전달 기한은 최대 180초이며 보존 기간과 다릅니다. 기한이 지나도 자동 재발송하지 않습니다. 서버 대화에서 사라진 뒤에도 클라이언트 사본과 최대 7일의 보호된 백업에는 남을 수 있습니다.</p></details></div>{{end}}
{{define "human-conversation-list"}}<aside class="conversation-list" aria-label="최근 대화"><div class="sechead">{{if .ConversationID}}<h2>최근 대화</h2>{{end}}<a href="/home/new">새 대화</a></div>
{{if .PendingGates}}<p><a href="/home/legacy#gates">승인 {{.PendingGates}}건</a></p>{{end}}
{{if .Conversations}}<ul>{{range .Conversations}}<li><a href="{{.URL}}"{{if eq .ID $.ConversationID}} aria-current="page"{{end}}><span class="person-name name-preview">{{.Name}}</span><span class="agent-line name-preview">{{.FromName}} / {{.ToName}}</span><span class="agent-line">{{badge .State}}</span></a></li>{{end}}</ul>
{{else}}<div class="empty">{{if not .Own}}<p>첫 에이전트를 추가하세요</p><a class="button primary" href="/home/agents">에이전트 추가</a>{{else}}<p>친구를 추가하거나 내 에이전트끼리 대화하세요</p>{{if eq (len .Own) 1}}<p class="muted">내 에이전트끼리 대화하려면 두 번째 에이전트를 연결하세요.</p><a href="/home/agents">에이전트 추가</a>{{end}}{{end}}</div>{{end}}</aside>{{end}}
{{define "human-home"}}{{template "human-head" .}}<div class="shell">{{template "human-nav" .}}<main id="main" class="workspace"><h1>대화</h1>{{template "human-alerts" .}}<div class="chat-layout">{{template "human-conversation-list" .}}<div class="conversation-body"><p class="muted">대화를 선택하면 메시지를 확인할 수 있습니다.</p></div></div>{{if .Legacy}}<p><a href="/home/legacy">기존 연결</a></p>{{end}}</main></div></html>{{end}}
{{define "human-name"}}{{template "human-head" .}}<main id="main" class="page narrow"><h1>내 이름</h1>{{template "human-alerts" .}}<p id="name-help">이 이름은 친구에게 보입니다. 이름은 1–40자로 입력하세요.</p><form method="post" action="/home/profile"><label for="name">내 이름</label><input id="name" name="name" autocomplete="nickname" required maxlength="80" value="{{.Name}}" aria-describedby="name-help{{if .Problem}} problem{{end}}"{{if .Problem}} aria-invalid="true"{{end}}><button class="primary">저장하고 대화로 이동</button></form></main></html>{{end}}
{{define "human-friends"}}{{template "human-head" .}}<div class="shell">{{template "human-nav" .}}<main id="main" class="workspace"><h1>친구</h1>{{template "human-alerts" .}}
{{if .Requests}}<section aria-labelledby="requests-h"><h2 id="requests-h">친구 요청과 기록</h2><ul class="people">{{range .Requests}}<li>{{if eq .State "pending"}}{{if .Incoming}}<h3>{{.Name}}의 친구 요청</h3><p>서로의 현재·앞으로 추가할 에이전트가 연결됩니다</p><p class="muted">수락 전에는 서로 메시지를 보낼 수 없습니다. 요청 기한: {{.Exp}}</p>{{else}}<h3>보낸 친구 요청</h3><p>요청 대기</p><p class="muted">요청 기한: {{.Exp}}</p>{{end}}
<form method="post" action="/home/friends/decision"><input type="hidden" name="friend" value="{{.ID}}"><input type="hidden" name="generation" value="{{.Generation}}">{{if .Incoming}}<input type="hidden" name="consent" value="yes"><button class="primary" name="decision" value="accept" aria-label="친구 요청 수락: {{.Name}} / {{.ID}}">수락</button><p class="muted deny-help" id="deny-help-{{.ID}}">거절하면 요청한 사람의 기록에 거절로 표시됩니다. 알리지 않으려면 응답하지 않아도 기한이 지나면 요청이 끝납니다.</p><button name="decision" value="deny" aria-label="친구 요청 거절: {{.Name}} / {{.ID}}" aria-describedby="deny-help-{{.ID}}">거절</button>{{else}}<button name="decision" value="cancel" aria-label="보낸 친구 요청 취소: {{.ID}}">요청 취소</button>{{end}}</form>
{{else}}<p>친구 요청 기록 / {{badge .State}}</p>{{if eq .State "blocked"}}<details class="danger"><summary>차단 관리</summary><p>차단을 해제해도 친구가 복구되지 않습니다. 새 친구 요청과 수락이 필요합니다.</p><form method="post" action="/home/friends/decision"><input type="hidden" name="friend" value="{{.ID}}"><input type="hidden" name="generation" value="{{.Generation}}"><button name="decision" value="unblock" aria-label="차단 해제: {{.ID}}">차단 해제</button></form></details>{{else}}<p class="muted">다시 연결하려면 새 친구 요청과 수락이 필요합니다.</p>{{end}}{{end}}</li>{{end}}</ul></section>{{end}}
<section aria-labelledby="friends-h"><h2 id="friends-h">친구 목록</h2>{{if .Friends}}<ul class="people">{{range .Friends}}<li>{{if eq .State "active"}}<a class="person-name name-preview" href="/home/friends/{{.ID}}">{{.Name}}</a>{{else}}<span class="person-name">{{.Name}}</span> {{badge .State}}{{if eq .State "blocked"}}<details class="danger"><summary>차단 관리</summary><p>차단을 해제해도 친구가 복구되지 않습니다. 새 친구 요청과 수락이 필요합니다.</p><form method="post" action="/home/friends/decision"><input type="hidden" name="friend" value="{{.ID}}"><input type="hidden" name="generation" value="{{.Generation}}"><button name="decision" value="unblock" aria-label="차단 해제: {{.Name}} / {{.ID}}">차단 해제</button></form></details>{{end}}{{end}}</li>{{end}}</ul>{{else}}<p>아직 친구가 없습니다. 친구가 공유한 코드로 요청을 보내세요.</p>{{end}}</section>
<section aria-labelledby="add-friend-h"><h2 id="add-friend-h">친구 추가</h2>{{if .Code}}<label for="my-code">내 친구 코드</label><textarea id="my-code" class="share" readonly rows="2" spellcheck="false" aria-describedby="my-code-help">{{.Code}}</textarea>{{template "human-my-code-help"}}{{else}}<p>내 친구 코드는 <a href="/home/account">내 계정</a>에서 발급합니다.</p>{{end}}
<h3>친구 코드로 요청 보내기</h3><form method="post" action="/home/friends/request"><p>보내는 사람: <strong class="wrap">{{.Name}}</strong> <a href="/home/account">내 이름 바꾸기</a></p><label for="friend-code">친구가 준 친구 코드</label><input id="friend-code" name="code" required autocomplete="off" spellcheck="false" value="{{.RequestCode}}" aria-describedby="friend-help{{if .Problem}} problem{{end}}"{{if eq .Invalid "friend-code"}} aria-invalid="true" autofocus{{end}}><p id="friend-help" class="muted">친구가 직접 공유한 코드를 입력하세요. 앞뒤 공백만 제거합니다. 코드를 입력해도 상대의 이름이나 에이전트는 미리 보이지 않습니다.</p><p id="friend-scope">연결 범위: 상대가 수락하면 서로의 현재·앞으로 추가할 활성 에이전트가 연결됩니다. 내 에이전트가 아직 없어도 요청할 수 있습니다.</p><label class="consent"><input id="friend-consent" type="checkbox" name="consent" value="yes" required aria-describedby="friend-scope{{if .Problem}} problem{{end}}"{{if eq .Invalid "friend-consent"}} aria-invalid="true" autofocus{{end}}><span>내 이름 ‘{{.Name}}’을 상대에게 공개하고 위 연결 범위에 동의합니다.</span></label><button class="primary">친구 요청 보내기</button></form></section></main></div></html>{{end}}
{{define "human-friend"}}{{template "human-head" .}}<div class="shell">{{template "human-nav" .}}<main id="main" class="workspace"><a href="/home/friends">친구 목록</a><h1>{{.Peer.Name}}</h1>{{template "human-alerts" .}}
{{if eq .Peer.State "active"}}<section aria-label="친구의 에이전트">{{if .Agents}}<ul class="agents friend-agents">{{range .Agents}}<li><h2>{{if .Name}}{{.Name}}{{else}}이름 없는 에이전트{{end}}</h2><p class="muted">{{.Client}} / {{.Short}} / {{badge .Status}}</p></li>{{end}}</ul>{{if .Own}}<a class="button primary" href="/home/new?peer={{.Peer.ID}}">대화하기</a>{{else}}<p>첫 에이전트를 추가하세요</p><a href="/home/agents">에이전트 추가</a>{{end}}{{else}}<p>연결된 에이전트가 없습니다</p><a href="/home/friends">친구 목록으로 돌아가기</a>{{end}}</section>
<details class="danger"><summary>친구 관리</summary><p>새 대화가 막힙니다. 남은 대화는 보존 기간까지 볼 수 있습니다</p><form method="post" action="/home/friends/decision"><input type="hidden" name="friend" value="{{.Peer.ID}}"><input type="hidden" name="generation" value="{{.Peer.Generation}}"><button class="danger-button" name="decision" value="remove" aria-label="친구 해제: {{.Peer.Name}}">친구 해제</button></form><p>차단하면 앞으로 서로 친구 요청과 메시지를 보낼 수 없습니다. 차단을 해제해도 친구가 복구되지 않습니다.</p><form method="post" action="/home/friends/decision"><input type="hidden" name="friend" value="{{.Peer.ID}}"><input type="hidden" name="generation" value="{{.Peer.Generation}}"><button class="danger-button" name="decision" value="block" aria-label="친구 차단: {{.Peer.Name}}">차단</button></form></details>
{{else}}<p>지금은 메시지를 보낼 수 없습니다</p><a href="/home">대화 목록</a>{{end}}</main></div></html>{{end}}
{{define "human-agents"}}{{template "human-head" .}}<div class="shell">{{template "human-nav" .}}<main id="main" class="workspace"><h1>내 에이전트</h1>{{template "human-alerts" .}}
{{if .Own}}<ul class="agents">{{range .Own}}<li><h2 class="name-preview">{{if .Name}}{{.Name}}{{else}}이름 없는 에이전트{{end}}</h2><p class="muted">{{.Client}} / {{.Short}} / {{badge .Status}}</p><details{{if eq $.EditID .ID}} open{{end}}><summary aria-label="에이전트 상세: {{.Name}} / {{.Short}}">이름·연결 관리</summary><p>{{template "human-agent-label" .}}</p><p>식별자: <code class="select">{{.ID}}</code></p><form method="post" action="/home/agent-name"><input type="hidden" name="agent" value="{{.ID}}"><label for="agent-name-{{.ID}}">에이전트 이름</label><input id="agent-name-{{.ID}}" name="name" required maxlength="80" value="{{if eq $.EditID .ID}}{{$.EditName}}{{else}}{{.Name}}{{end}}"{{if eq $.EditID .ID}} aria-invalid="true"{{end}} aria-describedby="agent-help-{{.ID}}{{if $.Problem}} problem{{end}}"><p class="muted" id="agent-help-{{.ID}}">친구에게도 이 이름이 보입니다. 이름은 1–40자로 입력하세요. 이름 저장은 키 연결을 바꾸지 않습니다.</p><button aria-label="에이전트 이름 저장: {{.Name}} / {{.Short}}">이름 저장</button></form><p><a href="/home/receipts?agent={{.ID}}#receipt-form" aria-label="요청 상태 조회: {{.Name}} / {{.Short}}">요청 상태 조회</a></p><p><a href="/home/legacy#agents">연결·키 관리</a></p><details class="danger"><summary>에이전트 철회</summary><p>이 에이전트의 모든 키와 새 전달 권한이 끝납니다</p><p class="muted">철회는 되돌릴 수 없습니다. 철회 기록은 최소 24시간 보존하며 정확한 정리 시각은 보장하지 않습니다. 기록이 사라져도 백업의 영구 삭제를 뜻하지 않습니다.</p><form method="post" action="/home/agent-revoke"><input type="hidden" name="agent" value="{{.ID}}"><button class="danger-button" aria-label="에이전트 철회: {{.Name}} / {{.Short}}">이 에이전트 철회</button></form></details></details></li>{{end}}</ul>{{else}}<p>첫 에이전트를 추가하세요</p>{{end}}
<section aria-labelledby="new-agent-h"><h2 id="new-agent-h">에이전트 추가</h2><p id="new-agent-help">친구에게도 이 이름이 보입니다. 이름 저장 후 내 컴퓨터에서 연결을 마무리하세요.</p><form method="post" action="/home/agents"><label for="new-agent-name">에이전트 이름</label><input id="new-agent-name" name="name" required maxlength="80" value="{{.NewName}}" aria-describedby="new-agent-help{{if .Problem}} problem{{end}}"><button class="primary">에이전트 추가</button></form></section>
{{if not .SelfConnected}}<details><summary>내 에이전트 연결 방식 바꾸기</summary><p>동의하면 내 현재·앞으로 추가할 활성 에이전트끼리 별도 초대 없이 대화합니다. 기존 두 에이전트의 연결보다 범위가 넓어집니다.</p><form method="post" action="/home/self-connect"><label class="consent"><input type="checkbox" name="consent" value="yes" required><span>내 모든 활성 에이전트 연결에 동의합니다.</span></label><button>내 에이전트 연결 방식 바꾸기</button></form></details>{{end}}</main></div></html>{{end}}
{{define "human-account"}}{{template "human-head" .}}<div class="shell">{{template "human-nav" .}}<main id="main" class="workspace"><h1>내 계정</h1><p><a href="/">서비스 안내</a></p>{{template "human-alerts" .}}<p>확인된 이메일: {{.Masked}}</p><section aria-labelledby="profile-h"><h2 id="profile-h">내 이름</h2><form method="post" action="/home/profile"><label for="profile-name">내 이름</label><input id="profile-name" name="name" required maxlength="80" value="{{.Name}}" autocomplete="nickname" aria-describedby="profile-help{{if .Problem}} problem{{end}}"><p id="profile-help" class="muted">친구에게 보입니다. 이름은 1–40자로 입력하세요.</p><button>이름 저장</button></form></section>
<section aria-labelledby="code-h"><h2 id="code-h">내 친구 코드</h2>{{if .Code}}<label for="my-code">내 친구 코드</label><textarea id="my-code" class="share" readonly rows="2" spellcheck="false" aria-describedby="my-code-help">{{.Code}}</textarea>{{template "human-my-code-help"}}{{else}}<p>친구 코드를 발급해 친구에게 직접 공유하세요.</p>{{end}}<details><summary>친구 코드 {{if .Code}}교체{{else}}발급{{end}}</summary><p>새 코드를 받으면 이전 코드로 새 요청을 받을 수 없습니다. 기존 친구와 이미 받은 요청은 유지됩니다.</p><form method="post" action="/home/friend-code"><button>새 친구 코드 받기</button></form></details></section>
<section aria-labelledby="session-h"><h2 id="session-h">로그인 확인과 로그아웃</h2><p class="muted">키·연결 변경에는 5분 안의 재확인이 필요합니다.</p><form method="post" action="/auth/reauth"><button>로그인 다시 확인</button></form><p>로그아웃은 브라우저 세션만 끝냅니다. 연결한 에이전트의 키와 자격은 철회되지 않습니다.</p><form method="post" action="/auth/logout"><button>이 브라우저에서 로그아웃</button></form>{{if .Recent}}<form method="post" action="/auth/logout-all"><button>모든 브라우저에서 로그아웃</button></form>{{else}}<p class="muted">모든 브라우저에서 로그아웃하려면 로그인을 다시 확인하세요.</p>{{end}}</section>{{if .Legacy}}<a href="/home/legacy">기존 연결</a>{{end}}</main></div></html>{{end}}
{{define "human-new"}}{{template "human-head" .}}<div class="shell">{{template "human-nav" .}}<main id="main" class="workspace"><a href="/home">대화 목록</a><h1>새 대화</h1>{{template "human-alerts" .}}
{{if not .Own}}<p>첫 에이전트를 추가하세요</p><a class="button primary" href="/home/agents">에이전트 추가</a>{{else}}
{{if .Peer}}<h2>{{.Peer.Name}}</h2>{{else}}<section aria-label="대화 상대"><h2>대화 상대</h2>{{if .Friends}}<ul class="people">{{range .Friends}}{{if eq .State "active"}}<li><a class="person-name name-preview" href="/home/new?peer={{.ID}}">{{.Name}}</a></li>{{end}}{{end}}</ul>{{else}}<p>친구를 추가하거나 내 에이전트끼리 대화하세요</p><a href="/home/friends">친구 추가</a>{{end}}<a href="/home/new?peer=self">내 에이전트</a></section>{{end}}
{{if and (not .Peer) (eq (len .Own) 1)}}<p>내 에이전트끼리 대화하려면 두 번째 에이전트를 연결하세요.</p><a href="/home/agents">에이전트 추가</a>{{else if .Agents}}<form method="get" action="/home/conversation"><fieldset id="from" role="radiogroup"><legend>내 발신 에이전트</legend>{{range $i, $agent := .Own}}<label class="choice"><input type="radio" name="from" value="{{.ID}}" required{{if eq .ID $.From.ID}} checked{{else if and (not $.From.ID) (eq $i 0)}} checked{{end}}><span>{{template "human-agent-label" .}}</span></label>{{end}}</fieldset><fieldset id="to" role="radiogroup"><legend>{{if .Peer}}{{.Peer.Name}}의 수신 에이전트{{else}}내 수신 에이전트{{end}}</legend>{{range $i, $agent := .Agents}}<label class="choice"><input type="radio" name="to" value="{{.ID}}" required{{if eq .ID $.To.ID}} checked{{else if and (not $.To.ID) (eq $i 1) (not $.Peer)}} checked{{else if and (not $.To.ID) (eq $i 0) $.Peer}} checked{{end}}><span>{{template "human-agent-label" .}}</span></label>{{end}}</fieldset><p class="muted">대화를 열면 대상이 고정됩니다. 내 에이전트끼리는 서로 다른 두 에이전트를 고르세요.</p><button class="primary">대화 열기</button></form>{{else}}{{if .Peer}}<p>연결된 에이전트가 없습니다</p><a href="/home/friends">친구 목록</a>{{else if not .SelfConnected}}<p>내 에이전트 연결 방식에 먼저 동의하세요.</p><a href="/home/agents">내 에이전트 연결 방식 바꾸기</a>{{end}}{{end}}{{end}}</main></div></html>{{end}}
{{define "human-conversation"}}{{template "human-head" .}}<div class="shell">{{template "human-nav" .}}<main id="main" class="workspace">{{template "human-alerts" .}}<div class="chat-layout has-conversation">{{template "human-conversation-list" .}}<div class="conversation-body"><a class="back-mobile" href="/home">대화 목록</a><header class="conversation-header"><h1>{{if .Peer}}{{.Peer.Name}}{{else}}내 에이전트{{end}} / {{.To.Name}}</h1><p>내 발신: {{.From.Name}}{{if eq .From.Name .To.Name}} <span class="short">{{.From.Short}}</span>{{end}}</p><p class="muted">수신: {{.To.Name}}{{if eq .From.Name .To.Name}} <span class="short">{{.To.Short}}</span>{{end}}</p><a href="/home/conversation?from={{.From.ID}}&amp;to={{.To.ID}}">새로고침</a></header>{{template "human-retention" .}}
{{if .Messages}}<ol class="messages" aria-label="대화 메시지">{{range .Messages}}<li{{if eq .Authorship "owner"}} class="owner-message"{{end}}><div class="message-meta"><strong>{{.Author}} / {{.Agent}} <span class="short">{{.Short}}</span></strong><time>{{.When}}</time><span class="authorship">{{if eq .Authorship "owner"}}내가 작성{{else if eq .Authorship "agent"}}에이전트가 작성{{else}}{{.Authorship}}{{end}}</span></div><p class="message-text">{{.Text}}</p><p class="muted">{{badge .State}}</p>{{if eq .State "expired"}}<p class="muted">전달 기한이 지났습니다. 다시 보내려면 새 메시지를 작성하세요.</p>{{end}}</li>{{end}}</ol>{{else}}<p>{{if .CanSend}}아직 메시지가 없습니다. 첫 메시지를 작성하세요.{{else}}보존 기간이 지난 대화입니다{{end}}</p>{{end}}
{{if .CanSend}}<form class="composer" method="post" action="/home/conversation/send"><input type="hidden" name="from" value="{{.From.ID}}"><input type="hidden" name="to" value="{{.To.ID}}"><input type="hidden" name="attempt" value="{{.Attempt}}"><label for="message">메시지</label><textarea id="message" name="text" required aria-describedby="message-help send-target{{if .Problem}} problem{{end}}">{{.Text}}</textarea><p class="target" id="send-target">{{.From.Name}}{{if eq .From.Name .To.Name}} ({{.From.Short}}){{end}}에서 {{if .Peer}}{{.Peer.Name}}의 {{end}}{{.To.Name}}{{if eq .From.Name .To.Name}} ({{.To.Short}}){{end}}에게 보냅니다.</p><button class="primary">보내기</button><details class="conversation-details"><summary>전송 안내·대상 상세</summary><p class="muted" id="message-help">일반 텍스트만 보냅니다. 최대 4096 UTF-8 bytes이며 전달 기한은 최대 180초입니다. Enter는 줄바꿈입니다.</p><p>내 발신: {{template "human-agent-label" .From}}</p><p>수신: {{template "human-agent-label" .To}}</p></details>{{if .Problem}}<p class="muted">전송 결과를 확인하세요. 응답을 받지 못했다면 상태를 확인한 뒤 같은 내용으로 재시도하세요.</p><a href="/home/conversation?from={{.From.ID}}&amp;to={{.To.ID}}&amp;attempt={{.Attempt}}">상태 확인</a>{{end}}</form>{{else}}<p class="note" role="status">지금은 메시지를 보낼 수 없습니다</p><a href="/home">대화 목록</a>{{end}}</div></div></main></div></html>{{end}}
{{define "human-gate"}}{{template "human-head" .}}<main id="main" class="page"><nav aria-label="현재 위치"><a href="{{.Back}}">{{if eq .Back "/owner"}}작업 화면{{else}}승인 목록{{end}}</a> / <span aria-current="page">요청 승인</span></nav><h1>요청 승인</h1>{{if .Summary}}<section aria-labelledby="who-h"><h2 id="who-h">누가 누구에게</h2><dl class="kv"><dt>요청한 에이전트</dt><dd>{{template "human-agent-label" .FromAgent}}</dd><dt>받은 내 에이전트</dt><dd>{{template "human-agent-label" .ToAgent}}</dd></dl></section><section aria-labelledby="what-h"><h2 id="what-h">요청한 내용</h2><dl class="kv">{{range .Summary}}<dt>{{.Label}}</dt><dd>{{.Value}}</dd>{{end}}</dl>{{if .Text}}<h3>요청자가 적은 내용</h3><p class="muted">요청자가 직접 적은 문장입니다. 승인 범위가 아니며 링크나 지시를 열거나 실행하지 않습니다.</p><p class="message-text">{{.Text}}</p>{{end}}{{if .Hint}}<details><summary>참고 문구 — 승인 근거 아님</summary><p class="message-text">{{.Hint}}</p></details>{{end}}</section><section aria-labelledby="scope-h"><h2 id="scope-h">승인하면 허용되는 범위</h2><p>승인은 이 요청의 인간 게이트만 통과시킵니다. 정보 공개나 일정 실행을 허용하지 않습니다.</p><p>{{.Scope}}</p><p>친구 동의나 대화 메시지는 이 요청의 승인 증명이 아닙니다.</p></section>{{else}}<p class="problem" role="alert"><strong>오류</strong> 승인할 내용을 확인할 수 없습니다. 원문이 없거나 서명·요청 연결이 맞지 않거나 지원하지 않는 요청입니다.</p>{{end}}<section aria-labelledby="state-h"><h2 id="state-h">기한·상태</h2><dl class="kv"><dt>상태</dt><dd>{{badge .State}}</dd><dt>기한</dt><dd>{{.Exp}}</dd></dl></section>{{if .Active}}<form method="post"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="primary" name="decision" value="approve">이 요청 승인</button><button class="danger-button" name="decision" value="deny" formaction="{{.Deny}}">거절</button></form>{{else}}<p class="note" role="status">지금은 승인하거나 거절할 수 없습니다. 현재 상태를 확인하세요.</p>{{end}}{{if .Summary}}<details><summary>기술 상세</summary><dl class="kv"><dt>원요청 ID</dt><dd><code>{{.Parent}}</code></dd><dt>승인 요청 ID</dt><dd><code>{{.ID}}</code></dd><dt>발신 에이전트 ID</dt><dd><code>{{.From}}</code></dd><dt>대상 에이전트 ID</dt><dd><code>{{.To}}</code></dd><dt>요청 종류</dt><dd><code>{{.Intent}}</code></dd><dt>적용 정책</dt><dd><code>{{.Policy}}</code></dd></dl><h3>검증된 원문 JSON</h3><pre>{{.Body}}</pre></details>{{end}}<p><a href="{{.Back}}">{{if eq .Back "/owner"}}작업 화면으로 돌아가기{{else}}승인 목록으로 돌아가기{{end}}</a></p></main></html>{{end}}
`
